-- Wilayah layanan (permintaan RS Tidar): alamat tujuan order memakai kode
-- wilayah Kemendagri 4 tingkat (provinsi, kab/kota, kecamatan, kelurahan/desa).
-- Order di luar wilayah layanan ditolak; ongkir tetap dari tier jarak.
-- Data: Kepmendagri No 300.2.2-2138 Tahun 2025, Jawa Tengah saja
-- (github.com/cahyadsn/wilayah, MIT).
CREATE TABLE regions (
    code VARCHAR(13) NOT NULL PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    level TINYINT UNSIGNED NOT NULL,
    parent_code VARCHAR(13) NULL,
    KEY regions_parent_code_index (parent_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

