-- dropoff_region: label kelurahan/kecamatan/kab saat order dibuat (riwayat tetap
-- terbaca walau data wilayah diperbarui).
ALTER TABLE orders
    ADD COLUMN dropoff_region_code VARCHAR(13) NULL AFTER dropoff_address,
    ADD COLUMN dropoff_region VARCHAR(255) NULL AFTER dropoff_region_code,
    ADD KEY orders_dropoff_region_code_index (dropoff_region_code);

ALTER TABLE customers
    ADD COLUMN region_code VARCHAR(13) NULL AFTER address;

-- Wilayah layanan awal: Kabupaten Magelang + Kota Magelang (diatur Admin di
-- Pengaturan → Wilayah Layanan).
INSERT INTO app_settings (name, value, updated_at) VALUES ('service_area', '33.08,33.71', NOW())
    ON DUPLICATE KEY UPDATE value = value;
